  UPDATE public.content_blocks SET content = '{"title":"","cta_gap":"12","lab_tip":"","cta_size":"md","key_idea":"<p>Si bien la disposición general de los vasos sanguíneos en ambas circulaciones es de arterias a capilares y después a venas, en algunas partes la circulación sistémica está modificada de manera que una vena o una arteriola se interpone entre dos redes capilares; estos vasos constituyen sistemas porta.<strong> Los sistemas porta venosos </strong>se encuentran en los vasos que llevan sangre hacia el hígado, el sistema porta hepático<strong> (vena porta)</strong> y en los vasos que irrigan la hipófisis, el <strong>sistema porta hipotálamo-hipofisario.</strong></p>","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"","badge_text":"Capas del Corazón","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","intro_text":"<p><strong>Corazón:</strong> Es una <strong>bomba muscular</strong> que mantiene el<strong> flujo unidireccional </strong>de la sangre.<span>&nbsp; </span>Posee músculo estriado cardiaco, un esqueleto fibroso y un sistema de conducción (fibras de Purkinje).</p><p>La pared del corazón está compuesta de <strong>tres capas</strong>:</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Epicardio:</strong> Capa más externa, también conocida como capa visceral de la serosa pericárdica. Se compone de una sola capa de células mesoteliales, así como de tejido conectivo y adiposo subyacente. En esta capa encontramos vasos sanguíneos y nervios.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Miocardio: </strong>Formada por músculo cardíaco.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>&nbsp; </strong></span><strong>Endocardio: </strong>Consiste en una capa interna de endotelio y tejido conectivo subendotelial junto y la capa subendocárdica que se continua con el tejido conjuntivo del miocardio.</p>","image_badge":"Diagrama de las capas del corazón","cta_position":"after","points_count":"0","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","cta_text_color":"#ffffff","__schema_version":"2"}'::jsonb
  WHERE id = '1c83d576-220c-4fee-b780-b9d3851adebe' AND content::jsonb = '{"title":"","cta_gap":"12","lab_tip":"","cta_size":"md","key_idea":"<p>Si bien la disposición general de los vasos sanguíneos en ambas circulaciones es de arterias a capilares y después a venas, en algunas partes la circulación sistémica está modificada de manera que una vena o una arteriola se interpone entre dos redes capilares; estos vasos constituyen sistemas porta.<strong> Los sistemas porta venosos </strong>se encuentran en los vasos que llevan sangre hacia el hígado, el sistema porta hepático<strong> (vena porta)</strong> y en los vasos que irrigan la hipófisis, el <strong>sistema porta hipotálamo-hipofisario.</strong></p>","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/atlas-content/1790482015851_captura_de_pantalla_2026-09-26_220640.webp","badge_text":"Capas del Corazón","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","intro_text":"<p><strong>Corazón:</strong> Es una <strong>bomba muscular</strong> que mantiene el<strong> flujo unidireccional </strong>de la sangre.<span>&nbsp; </span>Posee músculo estriado cardiaco, un esqueleto fibroso y un sistema de conducción (fibras de Purkinje).</p><p>La pared del corazón está compuesta de <strong>tres capas</strong>:</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Epicardio:</strong> Capa más externa, también conocida como capa visceral de la serosa pericárdica. Se compone de una sola capa de células mesoteliales, así como de tejido conectivo y adiposo subyacente. En esta capa encontramos vasos sanguíneos y nervios.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Miocardio: </strong>Formada por músculo cardíaco.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>&nbsp; </strong></span><strong>Endocardio: </strong>Consiste en una capa interna de endotelio y tejido conectivo subendotelial junto y la capa subendocárdica que se continua con el tejido conjuntivo del miocardio.</p>","image_badge":"Diagrama de las capas del corazón","cta_position":"after","points_count":"0","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","cta_text_color":"#ffffff","__schema_version":"2"}'::jsonb AND updated_at IS NOT DISTINCT FROM '2026-10-10T01:23:55.481837+00:00'::timestamptz;
