  IF affected <> 1 THEN RAISE EXCEPTION 'El registro content_blocks/1c83d576-220c-4fee-b780-b9d3851adebe cambió; operación cancelada'; END IF;
  UPDATE public.content_blocks SET content = '{"title":"Generalidades del Tejido","cta_gap":"12","lab_tip":"","cta_size":"md","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"","badge_text":"Fundamentos","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","intro_text":"El epitelio plano simple, consiste en una sola capa de células con escaso citoplasma, un núcleo aplanado y de posición basal. Cumple con diferentes funciones, como la capacidad de formar barreras entre el contenido de otros tejidos y el contenido sanguíneo, sin embargo, debido a su morfología, su función más destacada es el intercambio.","image_badge":"🔬 Micrografía de Referencia","cta_position":"after","point_1_desc":"","point_2_desc":"","point_3_desc":"","point_4_desc":"","points_count":"2","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","point_1_title":"Origen Embriológico","point_2_title":"Avascularidad & Difusión","point_3_title":"","point_4_title":"","cta_text_color":"#ffffff","__schema_version":"1"}'::jsonb
  WHERE id = '5e20ba09-f16d-4256-ba0a-14413e936654' AND content::jsonb = '{"title":"Generalidades del Tejido","cta_gap":"12","lab_tip":"","cta_size":"md","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/placas/sin_clasificar/ppepuh0g3qujispoiupv.webp","badge_text":"Fundamentos","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","intro_text":"El epitelio plano simple, consiste en una sola capa de células con escaso citoplasma, un núcleo aplanado y de posición basal. Cumple con diferentes funciones, como la capacidad de formar barreras entre el contenido de otros tejidos y el contenido sanguíneo, sin embargo, debido a su morfología, su función más destacada es el intercambio.","image_badge":"🔬 Micrografía de Referencia","cta_position":"after","point_1_desc":"","point_2_desc":"","point_3_desc":"","point_4_desc":"","points_count":"2","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","point_1_title":"Origen Embriológico","point_2_title":"Avascularidad & Difusión","point_3_title":"","point_4_title":"","cta_text_color":"#ffffff","__schema_version":"1"}'::jsonb AND updated_at IS NOT DISTINCT FROM '2026-08-25T16:55:13.321939+00:00'::timestamptz;
