  UPDATE public.content_blocks SET content = '{"text":"<p>El <strong>sistema cardiovascular</strong> se compone de un <strong>“sistema de tuberías”</strong> que son los vasos sanguíneos y una <strong>“bomba”</strong> que es el corazón, órgano muscular que impulsa la sangre a dos circuitos separados:</p><p>-<strong>Circuito Pulmonar:</strong> Se encarga de llevar la sangre <strong>desde el corazón hasta los pulmones y viceversa.</strong> En este proceso se da ese intercambio gaseoso conocido como <strong>hematosis</strong>. Al ser un circuito en el que la sangre recorre una corta distancia, a la circulación pulmonar también se le puede llamar circulación menor.</p><p>-<strong>Circuito Sistémico:</strong> Distribuye la sangre <strong>desde el corazón hacia los demás órganos y tejidos</strong> para proveerlos de oxígeno, nutrientes, y células inmunitarias; luego para eliminar productos de desecho metabólico y CO2, el viaje es desde los tejidos y órganos hasta el corazón de nuevo.</p>","ti_gap":"28","cta_gap":"12","ti_zoom":"true","cta_size":"md","ti_hover":"lift","ti_style":"editorial","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"","ti_accent":"#38bdf8","ti_filter":"none","ti_radius":"20","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","layout_tab":"","ti_loading":"lazy","cta_position":"after","ti_image_fit":"cover","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","image_caption":"<p>Vena mediana con tinción de Reticulina</p>","layout_column":"","ti_text_align":"left","cta_text_color":"#ffffff","image_position":"right","ti_image_width":"42","ti_caption_size":".82rem","ti_image_aspect":"auto","ti_image_height":"","ti_image_shadow":"medium","__schema_version":"2","layout_parent_id":"","ti_caption_align":"center","ti_vertical_align":"start","ti_object_position":"center center"}'::jsonb
  WHERE id = '7d074d99-278c-4c90-b1ff-4915e4a363d1' AND content::jsonb = '{"text":"<p>El <strong>sistema cardiovascular</strong> se compone de un <strong>“sistema de tuberías”</strong> que son los vasos sanguíneos y una <strong>“bomba”</strong> que es el corazón, órgano muscular que impulsa la sangre a dos circuitos separados:</p><p>-<strong>Circuito Pulmonar:</strong> Se encarga de llevar la sangre <strong>desde el corazón hasta los pulmones y viceversa.</strong> En este proceso se da ese intercambio gaseoso conocido como <strong>hematosis</strong>. Al ser un circuito en el que la sangre recorre una corta distancia, a la circulación pulmonar también se le puede llamar circulación menor.</p><p>-<strong>Circuito Sistémico:</strong> Distribuye la sangre <strong>desde el corazón hacia los demás órganos y tejidos</strong> para proveerlos de oxígeno, nutrientes, y células inmunitarias; luego para eliminar productos de desecho metabólico y CO2, el viaje es desde los tejidos y órganos hasta el corazón de nuevo.</p>","ti_gap":"28","cta_gap":"12","ti_zoom":"true","cta_size":"md","ti_hover":"lift","ti_style":"editorial","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/atlas-content/1790480116885_0031_m_l.webp","ti_accent":"#38bdf8","ti_filter":"none","ti_radius":"20","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","layout_tab":"","ti_loading":"lazy","cta_position":"after","ti_image_fit":"cover","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","image_caption":"<p>Vena mediana con tinción de Reticulina</p>","layout_column":"","ti_text_align":"left","cta_text_color":"#ffffff","image_position":"right","ti_image_width":"42","ti_caption_size":".82rem","ti_image_aspect":"auto","ti_image_height":"","ti_image_shadow":"medium","__schema_version":"2","layout_parent_id":"","ti_caption_align":"center","ti_vertical_align":"start","ti_object_position":"center center"}'::jsonb AND updated_at IS NOT DISTINCT FROM '2026-10-10T01:23:55.481837+00:00'::timestamptz;
