  UPDATE public.content_page_versions SET blocks = '[{"id":"7d074d99-278c-4c90-b1ff-4915e4a363d1","content":{"text":"<p>El <strong>sistema cardiovascular</strong> se compone de un <strong>“sistema de tuberías”</strong> que son los vasos sanguíneos y una <strong>“bomba”</strong> que es el corazón, órgano muscular que impulsa la sangre a dos circuitos separados:</p><p>-<strong>Circuito Pulmonar:</strong> Se encarga de llevar la sangre <strong>desde el corazón hasta los pulmones y viceversa.</strong> En este proceso se da ese intercambio gaseoso conocido como <strong>hematosis</strong>. Al ser un circuito en el que la sangre recorre una corta distancia, a la circulación pulmonar también se le puede llamar circulación menor.</p><p>-<strong>Circuito Sistémico:</strong> Distribuye la sangre <strong>desde el corazón hacia los demás órganos y tejidos</strong> para proveerlos de oxígeno, nutrientes, y células inmunitarias; luego para eliminar productos de desecho metabólico y CO2, el viaje es desde los tejidos y órganos hasta el corazón de nuevo.</p>","ti_gap":"28","cta_gap":"12","ti_zoom":"true","cta_size":"md","ti_hover":"lift","ti_style":"editorial","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"","ti_accent":"#38bdf8","ti_filter":"none","ti_radius":"20","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","layout_tab":"","ti_loading":"lazy","cta_position":"after","ti_image_fit":"cover","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","image_caption":"<p>Vena mediana con tinción de Reticulina</p>","layout_column":"","ti_text_align":"left","cta_text_color":"#ffffff","image_position":"right","ti_image_width":"42","ti_caption_size":".82rem","ti_image_aspect":"auto","ti_image_height":"","ti_image_shadow":"medium","__schema_version":"2","layout_parent_id":"","ti_caption_align":"center","ti_vertical_align":"start","ti_object_position":"center center"},"entity_id":37,"block_type":"text_image","sort_order":0,"entity_type":"subtemas_page"},{"id":"4bff1d04-3a3e-43e8-80dd-e29a843e1ae6","content":{"auto":"true","text":"<p><strong>Los vasos sanguíneos del sistema cardiovascular poseen tres componentes:</strong><br>-<strong>Arterias:</strong> transportan la sangre lejos del corazón. En su recorrido se van ramificando y reduciendo su diámetro.<span>&nbsp; </span>Las podemos subclasificar como arterias grandes, arterias medianas, arterias pequeñas y arteriolas.</p><p>-<strong>Capilares:</strong> Vasos de paredes finas con diámetro pequeño. Forman los lechos capilares donde se da un intercambio bidireccional entre la sangre y los tejidos.</p><p>-<strong>Venas:</strong> Drenan a los lechos capilares y forman vasos sanguíneos con un diámetro cada vez más grande hasta que devuelven la sangre de nuevo al corazón. Las podemos subclasificar en vénulas, venas pequeñas, venas medianas y venas grandes.</p>","tc_fit":"cover","tc_gap":"28","cta_gap":"12","tc_dots":"true","tc_zoom":"true","cta_size":"md","interval":"4","placa_id":"169","tc_style":"editorial","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","tc_accent":"#38bdf8","tc_arrows":"true","tc_aspect":"landscape","tc_filter":"none","tc_radius":"20","tc_shadow":"medium","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","tc_loading":"lazy","image_cap_1":"<p>Arteria mediana</p>","image_cap_2":"<p>Vena grande</p>","image_cap_3":"<p>Capilar</p><p></p>","image_url_1":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/placas/sin_clasificar/1790223719933_png.webp","image_url_2":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/placas/sin_clasificar/1790257219675_png.webp","image_url_3":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/placas/sin_clasificar/1790225769522_png.webp","tc_position":"center center","cta_position":"after","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","ti_text_align":"left","cta_text_color":"#ffffff","image_position":"right","tc_caption_size":".8rem","__schema_version":"1","tc_caption_align":"center","tc_gallery_width":"44","tc_vertical_align":"center"},"entity_id":37,"block_type":"text_carousel","sort_order":1,"entity_type":"subtemas_page"},{"id":"2c7134f9-5412-4904-aada-35b8a6b3ee00","content":{"title":"","cta_gap":"12","lab_tip":"","cta_size":"md","key_idea":"<p><strong>Lecho microcirculatorio:</strong> unidad funcional compuesta por las arteriolas, la red capilar asociada y las vénulas poscapilares. Al ser la porción más pequeña del sistema circulatorio, se encarga de regular el intercambio de sustancias entre la sangre y los tejidos.</p>","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/atlas-content/1791595428318_imagen_2026-10-09_192350524.webp","badge_text":"Composición de las Túnicas","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","intro_text":"<p>Estas capas poseen una composición general que puede varias ligeramente entre vasos sanguíneos:</p><p><strong>Túnica Íntima</strong>: Se compone de una sola capa de <strong>células endoteliales</strong> planas que reviste la luz del vaso y del <strong>tejido conectivo subendotelial, con la lámina elástica interna</strong> (LEI).</p><p><span>&nbsp;</span>-Las células endoteliales no solo cumplen la función de revestimiento, sino que también desempeñan otras funciones mediante componentes como:</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong> </strong></span><strong>Cuerpos de Weibel de Palade</strong></p><p><span style=\"font-family: Wingdings;\">  §</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp; </span><em><u>Adhesión Leucocitica:</u></em> Selectina P.</p><p><span style=\"font-family: Wingdings;\">  §</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp; </span><em><u>Coagulación</u></em>: Factor Tisular y Factor de Von     Willebrand.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Escinden Angiotensina I</strong> para generar angiotensina II.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Contienen lipoproteína-lipasa: </strong>enzima que degrada los trigliceridos de las lipoproteínas dando lugar a glicerol y ácidos grasos.</p><p><strong>Túnica Media:</strong><span><strong>&nbsp;</strong> </span>Por lo general la capa más gruesa de la pared del vaso, se compone de <strong>capas de músculo liso dispuestas de forma helicoida</strong>l y, cuando está presente, la <strong>lámina elástica externa</strong>. En los vasos pequeños, como los capilares y las vénulas poscapilares, no tienen túnica media, por lo que es remplazada por pericitos. <span>&nbsp;</span></p><p><strong>Túnica Adventicia: </strong>Es la capa más externa de la pared del vaso, se integra en el tejido conectivo circundante. Consta de un <strong>tejido conectivo denso irregular</strong> (fibras de colágeno tipo I y III), <strong>fibras elásticas orientadas longitudinalmente</strong> y <strong>vasa vasorum </strong>(riego sanguíneo de los vasos sanguíneos).</p>","layout_tab":"","line_color":"#6366f1","image_badge":"Diagrama de la composición general de las túnicas.","cta_position":"after","point_1_desc":"","points_count":"0","points_title":"","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","layout_column":"","point_1_title":"","cta_text_color":"#ffffff","__schema_version":"2","layout_parent_id":""},"entity_id":37,"block_type":"histology_generalities","sort_order":2,"entity_type":"subtemas_page"},{"id":"1c83d576-220c-4fee-b780-b9d3851adebe","content":{"title":"","cta_gap":"12","lab_tip":"","cta_size":"md","key_idea":"<p>Si bien la disposición general de los vasos sanguíneos en ambas circulaciones es de arterias a capilares y después a venas, en algunas partes la circulación sistémica está modificada de manera que una vena o una arteriola se interpone entre dos redes capilares; estos vasos constituyen sistemas porta.<strong> Los sistemas porta venosos </strong>se encuentran en los vasos que llevan sangre hacia el hígado, el sistema porta hepático<strong> (vena porta)</strong> y en los vasos que irrigan la hipófisis, el <strong>sistema porta hipotálamo-hipofisario.</strong></p>","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"","badge_text":"Capas del Corazón","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","intro_text":"<p><strong>Corazón:</strong> Es una <strong>bomba muscular</strong> que mantiene el<strong> flujo unidireccional </strong>de la sangre.<span>&nbsp; </span>Posee músculo estriado cardiaco, un esqueleto fibroso y un sistema de conducción (fibras de Purkinje).</p><p>La pared del corazón está compuesta de <strong>tres capas</strong>:</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Epicardio:</strong> Capa más externa, también conocida como capa visceral de la serosa pericárdica. Se compone de una sola capa de células mesoteliales, así como de tejido conectivo y adiposo subyacente. En esta capa encontramos vasos sanguíneos y nervios.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><strong>Miocardio: </strong>Formada por músculo cardíaco.</p><p><span style=\"font-family: Symbol;\">·</span><span style=\"font-size: 7pt; font-family: &quot;Times New Roman&quot;; font-weight: normal; line-height: normal;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong>&nbsp; </strong></span><strong>Endocardio: </strong>Consiste en una capa interna de endotelio y tejido conectivo subendotelial junto y la capa subendocárdica que se continua con el tejido conjuntivo del miocardio.</p>","image_badge":"Diagrama de las capas del corazón","cta_position":"after","points_count":"0","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","cta_text_color":"#ffffff","__schema_version":"2"},"entity_id":37,"block_type":"histology_generalities","sort_order":3,"entity_type":"subtemas_page"}]'::jsonb
  WHERE id = '229' AND blocks::jsonb = '[{"id":"7d074d99-278c-4c90-b1ff-4915e4a363d1","content":{"text":"<p>El <strong>sistema cardiovascular</strong> se compone de un <strong>“sistema de tuberías”</strong> que son los vasos sanguíneos y una <strong>“bomba”</strong> que es el corazón, órgano muscular que impulsa la sangre a dos circuitos separados:</p><p>-<strong>Circuito Pulmonar:</strong> Se encarga de llevar la sangre <strong>desde el corazón hasta los pulmones y viceversa.</strong> En este proceso se da ese intercambio gaseoso conocido como <strong>hematosis</strong>. Al ser un circuito en el que la sangre recorre una corta distancia, a la circulación pulmonar también se le puede llamar circulación menor.</p><p>-<strong>Circuito Sistémico:</strong> Distribuye la sangre <strong>desde el corazón hacia los demás órganos y tejidos</strong> para proveerlos de oxígeno, nutrientes, y células inmunitarias; luego para eliminar productos de desecho metabólico y CO2, el viaje es desde los tejidos y órganos hasta el corazón de nuevo.</p>","ti_gap":"28","cta_gap":"12","ti_zoom":"true","cta_size":"md","ti_hover":"lift","ti_style":"editorial","cta_1_url":"","cta_2_url":"","cta_3_url":"","cta_4_url":"","cta_align":"left","cta_color":"#2563eb","cta_shape":"rounded","cta_style":"soft","image_url":"https://pub-49025e2296604f9db7de3c958d1fdd8e.r2.dev/atlas-content/1790480116885_0031_m_l.webp","ti_accent":"#38bdf8","ti_filter":"none","ti_radius":"20","cta_1_text":"","cta_2_text":"","cta_3_text":"","cta_4_text":"","cta_layout":"row","layout_tab":"","ti_loading":"lazy","cta_position":"after","ti_image_fit":"cover","cta_1_new_tab":"false","cta_2_new_tab":"false","cta_3_new_tab":"false","cta_4_new_tab":"false","image_caption":"<p>Vena mediana con tinción de Reticulina</p>","layout_column":"","ti_text_align":"left","cta_text_color":"#ffffff","image_position":"right","ti_image_width":"42","ti_caption_size":".82rem","ti_image_aspect":"auto","ti_image_height":"","ti_image_shadow":"medium","